package com.sinoe.authmfa.web;
import com.sinoe.authmfa.dto.InstitutionAdminDtos.*; import com.sinoe.authmfa.security.InstitutionAccessService; import com.sinoe.authmfa.service.InstitutionAdminService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/institution") @RequiredArgsConstructor public class InstitutionAdminController {private final InstitutionAdminService service; private final com.sinoe.authmfa.service.InstitutionImportService imports; private final com.sinoe.authmfa.service.ExcelImportService excel; private final com.sinoe.authmfa.service.AuditService audit; private final com.sinoe.authmfa.service.InstitutionInvitationService invitations;
 @PostMapping("/users") public ResponseEntity<InvitationView> create(Authentication a,@Valid @RequestBody UserRequest r){return ResponseEntity.accepted().body(invitations.issue(ctx(a),actor(a),((InstitutionAccessService.Access)a.getDetails()).user().getAuthorizationVersion(),r.role(),r.email(),new ProfileUpdate(r.code(),r.department(),r.specialty(),r.career(),r.plan(),r.semester(),r.phone())));}

 @PostMapping("/users/invitations") public ResponseEntity<InvitationView> invite(Authentication a,@Valid @RequestBody InvitationRequest r){return ResponseEntity.accepted().body(invitations.issue(ctx(a),actor(a),((InstitutionAccessService.Access)a.getDetails()).user().getAuthorizationVersion(),r.role(),r.contactEmail(),r.profile()));}
 @PostMapping("/users/{id}/roles") public UserResponse role(Authentication a,@PathVariable long id,@Valid @RequestBody RoleRequest r){return service.addRole(ctx(a),id,r);}
 @DeleteMapping("/users/{id}/roles/{role}") public ResponseEntity<Void> revoke(Authentication a,@PathVariable long id,@PathVariable String role){service.revoke(ctx(a),id,role);return ResponseEntity.noContent().build();}
 @PatchMapping("/users/{id}/status") public UserResponse status(Authentication a,@PathVariable long id,@Valid @RequestBody StatusRequest r){return service.status(ctx(a),id,r.status());}
 @GetMapping("/users") public PageResponse users(Authentication a,@RequestParam(required=false) String q,@RequestParam(required=false) String role,@RequestParam(defaultValue="ACTIVE") String membershipStatus,@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Paginación inválida");return service.list(ctx(a),q,role,membershipStatus,status,page,size);}
 @GetMapping("/users/{id}") public UserDetail detail(Authentication a,@PathVariable long id){return service.detail(ctx(a),id);}
 @PutMapping("/users/{id}/profiles/{role}") public UserDetail profile(Authentication a,@PathVariable long id,@PathVariable String role,@Valid @RequestBody ProfileUpdate r){return service.updateProfile(ctx(a),id,role,r);}
 @PostMapping("/users/import-csv") public ImportReport csv(Authentication a,@RequestParam String role,@Valid @RequestBody ImportRequest r){return imports.importCsv(ctx(a),actor(a),((InstitutionAccessService.Access)a.getDetails()).user().getAuthorizationVersion(),role,r.csv());}
 @PostMapping(value="/users/import-excel",consumes="multipart/form-data") public ImportReport excel(Authentication a,@RequestParam String role,@RequestParam org.springframework.web.multipart.MultipartFile file){return imports.importCsv(ctx(a),actor(a),((InstitutionAccessService.Access)a.getDetails()).user().getAuthorizationVersion(),role,excel.readRows(file,12));}
 @PatchMapping("/users/{id}/roles/{role}/status") public UserDetail membership(Authentication a,@PathVariable long id,@PathVariable String role,@Valid @RequestBody StatusRequest r){return service.membershipStatus(ctx(a),id,role,r.status());}
 @GetMapping("/users/invitations") public Object pending(Authentication a,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return invitations.list(ctx(a),actor(a),((InstitutionAccessService.Access)a.getDetails()).user().getAuthorizationVersion(),page,size);}
 @PostMapping("/users/invitations/{id}/resend") public InvitationView resend(Authentication a,@PathVariable long id){return invitations.resend(ctx(a),actor(a),((InstitutionAccessService.Access)a.getDetails()).user().getAuthorizationVersion(),id);}
 @DeleteMapping("/users/invitations/{id}") public ResponseEntity<Void> cancel(Authentication a,@PathVariable long id){invitations.cancel(ctx(a),actor(a),((InstitutionAccessService.Access)a.getDetails()).user().getAuthorizationVersion(),id);return ResponseEntity.noContent().build();}
 private long actor(Authentication a){return ((InstitutionAccessService.Access)a.getDetails()).user().getId();}
 private long ctx(Authentication a){var x=(InstitutionAccessService.Access)a.getDetails();if(x.institutionId()==null)throw new IllegalStateException("Selecciona una institución");return x.institutionId();}}
